import { convertFileSrc, invoke, isTauri } from "@tauri-apps/api/core";
import { create } from "zustand";
import { useStore } from "../store";
import type { MediaItem } from "../types";

/**
 * Timeline visuals per media file: an audio peak envelope (waveform, also used
 * for ducking and beat detection) and a thumbnail sprite sheet for videos.
 * Generated by the backend (src-tauri/src/visuals.rs) in the background and
 * kept out of the main store, so they never touch undo history or the
 * project's dirty state.
 */

export interface Waveform {
  /** Peaks per second. */
  rate: number;
  /** Peak level per step, 0–255. */
  peaks: Uint8Array;
  /** Detected beats/onsets, in source seconds (computed on first use). */
  beats?: number[];
}

export interface ThumbStrip {
  url: string;
  /** Seconds between thumbnails. */
  interval: number;
  count: number;
  cols: number;
  tileW: number;
  tileH: number;
}

interface VisualsState {
  waves: Record<string, Waveform>;
  thumbs: Record<string, ThumbStrip>;
}

export const useVisuals = create<VisualsState>(() => ({ waves: {}, thumbs: {} }));

const requested = new Set<string>();
// One request at a time on our side too (the backend also serialises the work).
let chain: Promise<unknown> = Promise.resolve();
const enqueue = (fn: () => Promise<unknown>) => (chain = chain.then(fn, fn));

function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function request(m: MediaItem) {
  const key = `${m.id}|${m.path}`;
  if (requested.has(key)) return;
  requested.add(key);
  const wantsWave = m.kind === "audio" || (m.kind === "video" && m.probe?.hasAudio !== false);
  if (wantsWave) {
    enqueue(async () => {
      try {
        const w = await invoke<{ rate: number; peaks: string }>("media_waveform", { path: m.path });
        useVisuals.setState((s) => ({ waves: { ...s.waves, [m.id]: { rate: w.rate, peaks: decode(w.peaks) } } }));
      } catch {
        /* no audio stream: no waveform */
      }
    });
  }
  if (m.kind === "video" && m.duration > 0) {
    const hdr = m.probe?.hdr ? (m.probe.hdr === "HLG" || m.probe.color?.transfer === 18 ? "HLG" : "PQ") : null;
    enqueue(async () => {
      try {
        const t = await invoke<Omit<ThumbStrip, "url"> & { path: string }>("media_thumbnails", {
          path: m.path,
          duration: m.duration,
          aspect: m.width && m.height ? m.width / m.height : 16 / 9,
          hdr,
        });
        const strip: ThumbStrip = { url: convertFileSrc(t.path), interval: t.interval, count: t.count, cols: t.cols, tileW: t.tileW, tileH: t.tileH };
        useVisuals.setState((s) => ({ thumbs: { ...s.thumbs, [m.id]: strip } }));
      } catch {
        /* thumbnails are optional */
      }
    });
  }
}

/** Requests visuals for every usable media file, now and whenever media is added or relinked. */
export function installVisuals(): () => void {
  if (!isTauri()) return () => {};
  const scan = () => {
    for (const m of useStore.getState().media) {
      if ((m.status === "ready" || m.status === "proxying") && m.path && m.kind !== "image") request(m);
    }
  };
  scan();
  return useStore.subscribe((s, prev) => {
    if (s.media !== prev.media) scan();
  });
}

/** Peak (0–1) of a media file's audio at source time `t`, or null without a waveform. */
export function peakAt(w: Waveform, t: number): number {
  const i = Math.floor(t * w.rate);
  return i >= 0 && i < w.peaks.length ? w.peaks[i] / 255 : 0;
}

/**
 * Onsets (beats, hits) in a waveform, in source seconds: peaks of the rise in
 * energy that stand out from the surrounding second, at least 0.2 s apart.
 */
export function beatsOf(w: Waveform): number[] {
  if (w.beats) return w.beats;
  const { peaks, rate } = w;
  const n = peaks.length;
  const beats: number[] = [];
  if (n < rate) return (w.beats = beats);
  const energy = new Float32Array(n);
  for (let i = 0; i < n; i++) energy[i] = (peaks[i] / 255) ** 2;
  // Onset strength: rise over the average of the previous 50 ms.
  const back = Math.max(1, Math.round(rate * 0.05));
  const flux = new Float32Array(n);
  for (let i = back; i < n; i++) {
    let avg = 0;
    for (let j = i - back; j < i; j++) avg += energy[j];
    flux[i] = Math.max(0, energy[i] - avg / back);
  }
  // Adaptive threshold: mean + 1.5 σ over a 1 s window (prefix sums).
  const sum = new Float64Array(n + 1);
  const sq = new Float64Array(n + 1);
  for (let i = 0; i < n; i++) {
    sum[i + 1] = sum[i] + flux[i];
    sq[i + 1] = sq[i] + flux[i] * flux[i];
  }
  const half = Math.round(rate / 2);
  const gap = Math.round(rate * 0.2);
  let last = -Infinity;
  for (let i = 1; i < n - 1; i++) {
    if (flux[i] <= flux[i - 1] || flux[i] < flux[i + 1]) continue;
    const a = Math.max(0, i - half);
    const b = Math.min(n, i + half);
    const mean = (sum[b] - sum[a]) / (b - a);
    const sd = Math.sqrt(Math.max(0, (sq[b] - sq[a]) / (b - a) - mean * mean));
    if (flux[i] < mean + 1.5 * sd || flux[i] < 0.01) continue;
    if (i - last < gap) continue;
    beats.push(i / rate);
    last = i;
  }
  return (w.beats = beats);
}
